import * as d from "lib0/delta";
import { Node } from "prosemirror-model";
import { Transaction } from "prosemirror-state";
import { type Block, type BlockNoteEditor, type BlockSchema, type InlineContentSchema, type PartialBlock, type StyleSchema } from "../index.js";
import * as Y from "@y/y";
/**
 * Find the equivalent of a Y.Type in another Y.Doc.
 *
 * For root types this looks up the matching shared key; for sub-types it
 * locates the item by its client/clock ID in the target doc's store.
 */
export declare function findTypeInOtherYdoc<T extends Y.Type<any>>(ytype: T, otherYdoc: Y.Doc): T;
/**
 * Turn Prosemirror JSON to BlockNote style JSON
 * @param editor BlockNote editor
 * @param json Prosemirror JSON
 * @returns BlockNote style JSON
 */
export declare function _prosemirrorJSONToBlocks<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, json: any): Block<BSchema, ISchema, SSchema>[];
/**
 * Turn BlockNote JSON to Prosemirror node / state
 * @param editor BlockNote editor
 * @param blocks BlockNote blocks
 * @returns Prosemirror root node
 */
export declare function _blocksToProsemirrorNode<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, blocks: PartialBlock<BSchema, ISchema, SSchema>[]): Node;
/** YJS / BLOCKNOTE conversions */
/**
 * Turn a Y.Type collaborative doc into a BlockNote document (BlockNote style JSON of all blocks)
 * @param editor BlockNote editor
 * @param fragment Y.Type
 * @returns BlockNote document (BlockNote style JSON of all blocks)
 */
export declare function yfragmentToBlocks<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, fragment: Y.Type): Block<BSchema, ISchema, SSchema>[];
/**
 * Convert blocks to a Y.Type
 *
 * This can be used when importing existing content to Y.Doc for the first time,
 * note that this should not be used to rehydrate a Y.Doc from a database once
 * collaboration has begun as all history will be lost
 *
 * @param editor BlockNote editor
 * @param blocks the blocks to convert
 * @param fragment XML fragment name
 * @returns Y.Type
 */
export declare function blocksToYType<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, blocks: Block<BSchema, ISchema, SSchema>[], fragment?: Y.Type): Y.Type<any>;
/**
 * Turn a Y.Doc collaborative doc into a BlockNote document (BlockNote style JSON of all blocks)
 * @param editor BlockNote editor
 * @param ydoc Y.Doc
 * @param fragment XML fragment name
 * @returns BlockNote document (BlockNote style JSON of all blocks)
 */
export declare function yDocToBlocks<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, ydoc: Y.Doc, fragment?: string): Block<BSchema, ISchema, SSchema>[];
/**
 * This can be used when importing existing content to Y.Doc for the first time,
 * note that this should not be used to rehydrate a Y.Doc from a database once
 * collaboration has begun as all history will be lost
 *
 * @param editor BlockNote editor
 * @param blocks the blocks to convert
 * @param fragment XML fragment name
 */
export declare function blocksToYDoc<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, blocks: PartialBlock<BSchema, ISchema, SSchema>[], fragment?: string): Y.Doc;
/**
 * Diff two ProseMirror documents into a delta, using BlockNote's node-pairing
 * policy ({@link blockMatchNodes}) so a block's content-type change is reported
 * as a replace rather than a schema-invalid in-place edit.
 */
export declare function docDiffToDelta(previousDoc: Node, newDoc: Node): d.Delta<d.DeltaConf>;
/**
 * Build a ProseMirror transaction that turns `tr.doc` into the content of a
 * Y.Type `fragment`, applying the `renderer`'s authorship as
 * `y-attributed-*` marks. Used to render a (read-only) diff of a snapshot / a
 * version comparison into the editor.
 */
export declare function getProseMirrorTrFromYFragment({ tr, fragment, renderer, }: {
    tr: Transaction;
    fragment: Y.Type;
    renderer?: Y.AbstractRenderer | null;
}): Transaction;
